// ========================================================
// Google Review Request (MIT) - "Decide" node
// Edit CONFIG below. Leave the rest alone.
// ========================================================
const CONFIG = {
  businessName: 'Your Business',             // shown in every SMS (Spam Act: sender identification)
  timezone: 'Australia/Brisbane',
  googleReviewUrl: 'https://g.page/r/YOUR-PLACE-ID/review',
  delayHours: 2,                               // wait this long after "job complete"
  repeatDays: 180,                             // don't ask the same number again within this many days
  sendWindow: { days: [1, 2, 3, 4, 5], start: '09:00', end: '19:00' }, // 0=Sun..6=Sat
  sms: {
    enabled: true, provider: 'twilio',
    from: '+61491570156',                      // your Twilio AU mobile number
    twilioAccountSid: 'ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
    twilioBaseUrl: 'https://api.twilio.com',
  },
  maxMessagesPerDay: 50, maxPerCustomerPerDay: 1, sendOptOutConfirmation: true, sharedSecret: '',
  templates: {
    requestSms: "Hi {name}, thanks for choosing {business}. If you have a minute, an honest Google review really helps a local business: {link} Reply STOP to opt out",
    optOutConfirm: "You won't get more texts from {business}. Reply START to undo.",
  },
};
// ========================================================
const req = $input.first().json;

// ============ Shared engine (leave the rest alone) ============
// Expects CONFIG and req to be defined above. Everything below is generic plumbing:
// AU phone handling, time zones, send windows, opt-outs, caps and message queueing.
const isWebhook = !!(req && req.headers);
const body = isWebhook && req.body && typeof req.body === 'object' ? req.body : {};
const query = (isWebhook && req.query) || {};
const route = isWebhook ? String(String(req.webhookUrl || '').split('?')[0].split('/').pop() || '').toLowerCase() : 'run-due';
const store = $getWorkflowStaticData('global');
for (const k of ['optOut', 'counts', 'contacts']) store[k] = store[k] || {};
store.records = store.records || {};
const hdrKey = isWebhook && req.headers ? (req.headers['x-pack-key'] || '') : '';
const keyOk = !CONFIG.sharedSecret || query.key === CONFIG.sharedSecret || hdrKey === CONFIG.sharedSecret;
let now = new Date();
if (CONFIG.allowSimulatedTime && keyOk && (query.now || body.now)) {
  const t = Date.parse(query.now || body.now);
  if (!isNaN(t)) now = new Date(t);
}
const TZ = CONFIG.timezone || 'Australia/Brisbane';
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

function parts(date) {
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-AU', { timeZone: TZ, weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date).map(x => [x.type, x.value]));
  const hh = p.hour === '24' ? '00' : p.hour;
  return { y: +p.year, m: +p.month, d: +p.day, hh: +hh, mi: +p.minute, dow: DAYS.indexOf(p.weekday), date: `${p.year}-${p.month}-${p.day}`, hhmm: `${hh}:${p.minute}` };
}
function tzOffsetMs(date) { const p = parts(date); return Date.UTC(p.y, p.m - 1, p.d, p.hh, p.mi) - Math.floor(date.getTime() / 60000) * 60000; }
function zoned(dateStr, hhmm) { // local wall-clock time in CONFIG.timezone -> Date (DST-safe)
  const [y, m, d] = dateStr.split('-').map(Number); const [h, mi] = String(hhmm || '00:00').split(':').map(Number);
  const guess = Date.UTC(y, m - 1, d, h, mi); let t = guess - tzOffsetMs(new Date(guess)); t = guess - tzOffsetMs(new Date(t)); return new Date(t);
}
function addDaysStr(dateStr, n) { const [y, m, d] = dateStr.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10); }
function dowOf(dateStr) { return new Date(dateStr + 'T00:00:00Z').getUTCDay(); }
function inClosedown(dateStr) {
  const c = CONFIG.closedown; if (!c || !c.from || !c.to) return false; const md = dateStr.slice(5);
  return c.from <= c.to ? (md >= c.from && md <= c.to) : (md >= c.from || md <= c.to);
}
function isHoliday(dateStr) { return (CONFIG.publicHolidays || []).includes(dateStr) || inClosedown(dateStr); }
function windowFor(dateStr, w) { const d = dowOf(dateStr); const sat = w.saturday && d === 6 ? w.saturday : null; return sat || (w.days.includes(d) ? w : null); }
function isSendDay(dateStr, w) { return !!windowFor(dateStr, w) && !isHoliday(dateStr); }
function nextSendTime(date, w) { // earliest moment >= date inside the send window (skips holidays/closedown)
  w = w || CONFIG.sendWindow; let ds = parts(date).date;
  for (let i = 0; i < 90; i++) {
    if (isSendDay(ds, w)) {
      const win = windowFor(ds, w); const start = zoned(ds, win.start), end = zoned(ds, win.end);
      if (i > 0 || date < start) return start;
      if (date < end) return date;
    }
    ds = addDaysStr(ds, 1);
  }
  return date;
}
function inWindow(date, w) { return nextSendTime(date, w).getTime() === date.getTime(); }
function addSendDays(dateStr, n, w) { // n business (send) days after dateStr
  w = w || CONFIG.sendWindow; let ds = dateStr, c = 0, guard = 0;
  while (c < n && guard++ < 400) { ds = addDaysStr(ds, 1); if (isSendDay(ds, w)) c++; }
  return ds;
}
function validYMD(y, mo, d) { const t = new Date(Date.UTC(+y, +mo - 1, +d)); return t.getUTCFullYear() === +y && t.getUTCMonth() === +mo - 1 && t.getUTCDate() === +d; }
function parseLocal(v) { // ISO with offset, 'YYYY-MM-DD HH:mm', 'YYYY-MM-DD' or AU 'DD/MM/YYYY [HH:mm]' -> Date (null if not a real date)
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[ T](\d{1,2}):(\d{2}))?$/);
  if (m) return validYMD(m[3], m[2], m[1]) && +(m[4] || 0) < 24 && +(m[5] || 0) < 60 ? zoned(`${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`, `${m[4] || '00'}:${m[5] || '00'}`) : null;
  m = s.match(/^((\d{4})-(\d{2})-(\d{2}))(?:[ T](\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?)?$/);
  if (m) return validYMD(m[2], m[3], m[4]) && +(m[5] || 0) < 24 && +(m[6] || 0) < 60 ? zoned(m[1], `${m[5] || '00'}:${m[6] || '00'}`) : null;
  const t = Date.parse(s); return isNaN(t) ? null : new Date(t);
}
function fmtDay(date) { return new Intl.DateTimeFormat('en-AU', { timeZone: TZ, weekday: 'short', day: 'numeric', month: 'short' }).format(date).replace(',', ''); }
function fmtTime(date) { const p = parts(date); const h = p.hh % 12 || 12; return `${h}${p.mi ? ':' + String(p.mi).padStart(2, '0') : ''}${p.hh < 12 ? 'am' : 'pm'}`; }
function fmtDMY(dateOrStr) { const s = typeof dateOrStr === 'string' ? dateOrStr : parts(dateOrStr).date; const [y, m, d] = s.split('-'); return `${d}/${m}/${y}`; }
function aud(n) { return 'A$' + Number(n || 0).toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function money(v) { if (typeof v === 'number') return isFinite(v) ? Math.round(v * 100) / 100 : NaN; const t = String(v === undefined || v === null ? '' : v).replace(/[\s,$]|A\$|AUD/gi, ''); if (!/^-?\d+(\.\d+)?$/.test(t)) return NaN; return Math.round(Number(t) * 100) / 100; }

function toE164AU(raw) {
  if (raw === undefined || raw === null) return null;
  let s = String(raw).trim().replace(/[\s\-().]/g, '');
  if (!s) return null;
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (/^0[2-9]\d{8}$/.test(s)) s = '+61' + s.slice(1);
  else if (/^61[2-9]\d{8}$/.test(s)) s = '+' + s;
  else if (/^[2-9]\d{8}$/.test(s)) s = '+61' + s;
  return /^\+\d{8,15}$/.test(s) ? s : null;
}
const isAuMobile = n => /^\+614\d{8}$/.test(n || '');
const isEmail = e => /^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']{2,}$/.test(String(e || ''));
const clean = (v, max) => String(v === undefined || v === null ? '' : v).replace(/[\r\n\t]+/g, ' ').replace(/\s{2,}/g, ' ').trim().slice(0, max || 200);
const fill = (tpl, vars) => String(tpl || '').replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined && vars[k] !== null ? String(vars[k]) : m));
const esc = s => String(s === undefined || s === null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
function fnv(str) { let h = 0x811c9dc5; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(36); }
function token(ref) { return `${ref}.${fnv(ref + '|' + (CONFIG.sharedSecret || '') + '|' + CONFIG.businessName)}`; }
function fromToken(t) { const ref = String(t || '').split('.')[0]; return ref && token(ref) === String(t) ? ref : null; }
function newRef(prefix) { return prefix + parts(now).date.slice(2).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase(); }
function firstName(n) { return clean(n, 80).split(' ')[0] || 'there'; }

const owner = toE164AU(CONFIG.ownerMobile);
const messages = [];
const notes = [];
const today = parts(now).date;
function dayBucket() { if (!store.counts[today]) store.counts = { [today]: { total: 0, per: {} } }; return store.counts[today]; }
function optedOut(addr) { return !!(addr && store.optOut[String(addr).toLowerCase()]); }
function optOut(addr, why) { if (addr) store.optOut[String(addr).toLowerCase()] = { at: now.toISOString(), why: why || 'stop' }; }
function weeklyOk(key) { // contact-frequency guard per customer (rolling 7 and 30 days)
  const lim = CONFIG.contactLimits; if (!lim || !key) return true;
  const list = (store.contacts[key] || []).filter(t => now.getTime() - t < 30 * 86400000); store.contacts[key] = list;
  const week = list.filter(t => now.getTime() - t < 7 * 86400000).length;
  return week < lim.perWeek && list.length < lim.perMonth;
}
function noteContact(key) { if (CONFIG.contactLimits && key) (store.contacts[key] = store.contacts[key] || []).push(now.getTime()); }
function sentToday(to) { const k = String(to).toLowerCase(); return (dayBucket().per[k] || dayBucket().per[to] || 0) + messages.filter(m => m.purpose !== 'owner' && String(m.to).toLowerCase() === k).length; }
function canSms(to, opts) {
  opts = opts || {};
  if (!CONFIG.sms || !CONFIG.sms.enabled) { notes.push('sms channel disabled'); return false; }
  if (!isAuMobile(to)) { notes.push(`not an AU mobile: ${to}`); return false; }
  if (!opts.owner && optedOut(to)) { notes.push(`opted out: ${to}`); return false; }
  const day = dayBucket();
  if (day.total + messages.length >= CONFIG.maxMessagesPerDay) { notes.push('daily cap reached'); return false; }
  if (!opts.owner && sentToday(to) >= CONFIG.maxPerCustomerPerDay) { notes.push(`per-customer cap reached: ${to}`); return false; }
  return true;
}
function canEmail(to, opts) {
  opts = opts || {};
  if (!CONFIG.email || !CONFIG.email.enabled) { notes.push('email channel disabled'); return false; }
  if (!isEmail(to)) { notes.push(`invalid email: ${to}`); return false; }
  if (!opts.owner && optedOut(to)) { notes.push(`opted out: ${to}`); return false; }
  const day = dayBucket();
  if (day.total + messages.length >= CONFIG.maxMessagesPerDay) { notes.push('daily cap reached'); return false; }
  if (!opts.owner && sentToday(to) >= CONFIG.maxPerCustomerPerDay) { notes.push(`per-customer cap reached: ${to}`); return false; }
  return true;
}
function queueSms(to, text, purpose, ref) { messages.push({ channel: 'sms', to, from: CONFIG.sms.from, body: clean(text, 640), purpose, ref: ref || '' }); }
function queueEmail(to, subject, text, html, purpose, ref) { messages.push({ channel: 'email', to, from: CONFIG.email.from, replyTo: CONFIG.email.replyTo || '', subject: clean(subject, 160), text, html, purpose, ref: ref || '' }); }
function alertOwner(text, ref) {
  if (!CONFIG.ownerAlerts) return;
  if (owner && canSms(owner, { owner: true })) queueSms(owner, text, 'owner', ref);
  if (CONFIG.ownerEmail && canEmail(CONFIG.ownerEmail, { owner: true })) queueEmail(CONFIG.ownerEmail, `[${CONFIG.businessName}] ${clean(text, 70)}`, text, `<p>${esc(text)}</p>`, 'owner', ref);
}
function unsubUrl(ref) { return `${CONFIG.publicBaseUrl}/unsubscribe?t=${encodeURIComponent(token(ref))}`; }
function emailHtml(paras, cta, ref) { // simple, mobile-friendly, plain-looking HTML email with sender ID + unsubscribe
  const p = paras.filter(Boolean).map(x => `<p style="margin:0 0 14px">${esc(x)}</p>`).join('');
  const b = cta && cta.url ? `<p style="margin:18px 0"><a href="${esc(cta.url)}" style="background:${CONFIG.email.brandColour || '#0b5fff'};color:#fff;text-decoration:none;padding:12px 18px;border-radius:6px;display:inline-block;font-weight:600">${esc(cta.text)}</a></p>` : '';
  const extra = (CONFIG.email.footerLines || []).filter(Boolean).map(esc).join('<br>');
  return `<!doctype html><html><body style="margin:0;background:#f4f5f7"><div style="max-width:560px;margin:0 auto;padding:24px;font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5;color:#1d2433;background:#fff">${p}${b}<hr style="border:none;border-top:1px solid #e3e6eb;margin:22px 0"><p style="font-size:12px;color:#6b7280;margin:0">${esc(CONFIG.businessName)}${CONFIG.abn ? ' &middot; ABN ' + esc(CONFIG.abn) : ''}${extra ? '<br>' + extra : ''}<br>Don't want these emails? <a href="${esc(unsubUrl(ref))}" style="color:#6b7280">Unsubscribe</a>.</p></div></body></html>`;
}
function emailText(paras, cta, ref) {
  return paras.filter(Boolean).join('\n\n') + (cta && cta.url ? `\n\n${cta.text}: ${cta.url}` : '') + `\n\n--\n${CONFIG.businessName}${CONFIG.abn ? ' | ABN ' + CONFIG.abn : ''}\nUnsubscribe: ${unsubUrl(ref)}`;
}
const STOP_RE = CONFIG.cancelMeansOptOut === false ? /^\s*(stop|stopall|unsubscribe|cancel all|end|quit|opt ?out)\b/i : /^\s*(stop|stopall|unsubscribe|cancel|end|quit|opt ?out)\b/i;
const START_RE = /^\s*(start|unstop|subscribe)\b/i;
function inboundFields() {
  return { from: toE164AU(body.From || body.from || body.sender || body.msisdn), text: clean(body.Body || body.body || body.message || body.text, 600), isTwilio: !!(body.MessageSid || body.AccountSid) };
}
function smsReplyResponse(isTwilio, action) {
  return isTwilio ? { kind: 'normal', status: 200, contentType: 'text/xml', body: '<?xml version="1.0" encoding="UTF-8"?><Response></Response>' }
    : { kind: 'normal', status: 200, contentType: 'application/json', body: JSON.stringify({ ok: true, action }) };
}
function json(status, obj) { return { kind: 'normal', status, contentType: 'application/json', body: JSON.stringify(obj) }; }
function page(title, text, status) {
  return { kind: 'normal', status: status || 200, contentType: 'text/html; charset=utf-8', body: `<!doctype html><meta name=viewport content="width=device-width"><title>${esc(title)}</title><body style="font-family:Arial,sans-serif;max-width:32rem;margin:3rem auto;padding:0 1rem;color:#1d2433"><h2>${esc(title)}</h2><p>${esc(text)}</p><p style="color:#6b7280">${esc(CONFIG.businessName)}</p></body>` };
}
function handleUnsubscribe(recordsWithContacts) {
  const ref = fromToken(query.t);
  const rec = ref && store.records[ref];
  if (!rec) return { action: 'unsubscribe:invalid', response: page('Link not recognised', 'This unsubscribe link is invalid or has expired. Reply to any of our messages and we will remove you.', 400) };
  for (const a of [rec.email, rec.phone]) optOut(a, 'unsubscribe-link');
  return { action: 'unsubscribe:ok', response: page("You're unsubscribed", `You won't get any more automated messages from ${CONFIG.businessName}.`) };
}
function handleStopStart(from, text) { // returns action string or null
  if (STOP_RE.test(text)) {
    const already = optedOut(from);
    optOut(from, 'sms-stop');
    for (const r of Object.values(store.records)) if (r.phone === from && r.email) optOut(r.email, 'sms-stop'); // one opt-out covers all channels
    if (CONFIG.sendOptOutConfirmation && !already && isAuMobile(from) && CONFIG.sms.enabled) queueSms(from, fill(CONFIG.templates.optOutConfirm, { business: CONFIG.businessName }), 'customer:opt-out-confirm');
    return 'sms-inbound:opt-out';
  }
  if (START_RE.test(text)) {
    delete store.optOut[from];
    for (const r of Object.values(store.records)) if (r.phone === from && r.email) delete store.optOut[String(r.email).toLowerCase()];
    return 'sms-inbound:opt-in';
  }
  return null;
}
function finish(action, response, extra) {
  if (messages.length) {
    const day = dayBucket();
    for (const m of messages) { day.total++; const k = String(m.to).toLowerCase(); if (m.purpose !== 'owner') day.per[k] = (day.per[k] || 0) + 1; }
  }
  return [{ json: Object.assign({
    route, action, at: now.toISOString(), notes, messages, response: response || { kind: 'none' },
    smsProvider: CONFIG.sms ? CONFIG.sms.provider : 'dryrun', emailProvider: CONFIG.email ? CONFIG.email.provider : 'dryrun',
    sms: CONFIG.sms ? { twilioAccountSid: CONFIG.sms.twilioAccountSid, twilioBaseUrl: CONFIG.sms.twilioBaseUrl, clicksendBaseUrl: CONFIG.sms.clicksendBaseUrl } : {},
  }, extra || {}) }];
}
function pruneRecords(maxAgeDays, maxCount) {
  const ids = Object.keys(store.records);
  for (const id of ids) { const r = store.records[id]; if (now.getTime() - Date.parse(r.createdAt) > maxAgeDays * 86400000) delete store.records[id]; }
  const left = Object.values(store.records).sort((a, b) => Date.parse(a.createdAt) - Date.parse(b.createdAt));
  while (left.length > maxCount) delete store.records[left.shift().ref];
