// ============ end of shared engine ============

// ---- Logic: one review request per job, SMS only ----
function processDue() {
  let sent = 0;
  if (!inWindow(now)) return 0;
  for (const r of Object.values(store.records)) {
    if (r.stage !== 'scheduled' || Date.parse(r.dueAt) > now.getTime()) continue;
    if (canSms(r.phone)) { queueSms(r.phone, fill(CONFIG.templates.requestSms, { name: firstName(r.name), business: CONFIG.businessName, link: CONFIG.googleReviewUrl }), 'customer:review-request', r.ref); sent++; r.stage = 'requested'; }
