  const phone = toE164AU(body.phone || body.mobile), name = clean(body.name, 80);
  store.asked = store.asked || {};
  if (!name || !isAuMobile(phone)) { action = 'job-complete:invalid'; response = json(400, { ok: false, errors: ['name and an AU mobile are required'] }); }
  else if (optedOut(phone) || (store.asked[phone] && now.getTime() - store.asked[phone] < CONFIG.repeatDays * 86400000)) { action = 'job-complete:skipped'; response = json(200, { ok: true, scheduled: false }); }
  else {
    const ref = newRef('R');
    store.records[ref] = { ref, name, phone, createdAt: now.toISOString(), stage: 'scheduled', dueAt: nextSendTime(new Date(now.getTime() + CONFIG.delayHours * 3600000)).toISOString() };
    store.asked[phone] = now.getTime();
